
import { Asset, js } from "cc";
import { i18nConfig } from "../i18n/i18nConfig";

export class ConfigUtil {

    private static s_configs: any;

    /**
     * 初始化
     */
    public static init(data: any): void {
        i18nConfig.initConfig(data);
    }

    /**
     * 获取配置文件
     * 示例：let configs:Dictionary<HeadConfig> = Config.getConfig(HeadConfig);
     * let configs:Dictionary<HeadConfig> = Config.getConfig(HeadConfig);
     * configs.get('1').emojiID;
     */
    public static getConfig<T>(name: string): any {
        return ConfigUtil.s_configs[name];
    }
}