import {
    _decorator,
    SafeArea,
    sys,
    Widget,
    view,
    macro,
    UITransform,
    Node,
} from "cc";
import { JSB } from "cc/env";
const { ccclass, property } = _decorator;

@ccclass("UISafeArea")
export class UISafeArea extends SafeArea {
    private orientation: number = 0;
    @property(Node)
    private gameScrollViewNode: Node = null;

    onLoad() {
        super.onEnable();
        this.changeArea();
        this.doAdaptGameListNode();
        view.on("canvas-resize", this.onUpdateArea.bind(this));
    }
    private doAdaptGameListNode() {
        if (!this.gameScrollViewNode) return;
        this.gameScrollViewNode.getComponent(UITransform).width =
            view.getVisibleSize().width -
            this.gameScrollViewNode.getComponent(Widget).left;
    }

    private onUpdateArea() {
        this.doAdaptGameListNode();
        if (!JSB) return;
        let area = sys.getSafeAreaRect();
        if (area.x == 0 && area.y == 0) return;
        this.schedule(
            () => {
                if (JSB) {
                    if (
                        this.orientation !== jsb.device.getDeviceOrientation()
                    ) {
                        this.unscheduleAllCallbacks();
                        this.changeArea();
                    }
                }
            },
            0.1,
            macro.REPEAT_FOREVER,
            0.01
        );
    }

    private changeArea() {
        if (!JSB) return;
        let area = sys.getSafeAreaRect();
        Log.d(`area=${area.x},${area.y},${area.width},${area.height}`);
        if (area.x == 0 && area.y == 0) return;
        this.orientation = jsb.device.getDeviceOrientation();
        this.scheduleOnce(() => {
            let widget = this.node.getComponent(Widget);
            let safe = this.node.getComponent(SafeArea);
            if (!widget || !safe) return;
            Log.d(
                `widget1=${widget.left},${widget.right},${widget.bottom},${widget.top}`
            );

            if (this.orientation === 90) {
                widget.left = area.x - 30;
                widget.right = 0;
            } else if (this.orientation === -90) {
                widget.left = 0;
                widget.right = 0;
            }
            widget.updateAlignment();
            for (let child of this.node.children) {
                let cWidget = child.getComponent(Widget);
                if (cWidget) {
                    cWidget.updateAlignment();
                }
                Log.d(
                    `cWidget=${cWidget.name},${cWidget.left},${cWidget.right}`
                );
            }
        });
    }
}
