export class CurrencyUtil {

    /** 不使用币种特殊符号的游戏id */
    private static _nonuseSymbolGameId = [
    ];
    public static get nonuseSymbolGameId(): number[] {
        return this._nonuseSymbolGameId;
    }

    private static _currencySymbol: { [key: string]: string } = {
        'NPR': '₨',
        'KRW': '₩',
        'BDT': 'BDT',
        'INR': '₹',
        'BRL': 'R$',
        'CAD': 'C$',
        'BND': 'B$',
        'AUD': 'A$',
        'MMK': 'MMK',
        'IDR': 'RP',
        'THB': '฿',
        'VND': '₫',
        'MYR': 'RM',
        'USD': '$',
        'EUR': '€',
        'GBP': '£',
        'JPY': '￥',
        'NZD': 'NZ$',
        'SEK': 'Kr',
        'SGD': 'S$',
        'RUB': '₽',
        'ZAR': 'R',
        'KES': 'K',
        'NGN': '₦',
        'ETB': 'Br',
        'XAF': 'FCFA',
        'XOF': 'CFA',
        'TZS': 'TSh',
        'CDF': 'FC',
        'RWF': 'RF',
        'UGX': 'Ush',

    }

    /** 币种符号 */
    public static currencySymbol(currency: string): string {
        let symbol = currency;
        if (this._currencySymbol[currency])
            symbol = this._currencySymbol[currency];
        else
            symbol = `${symbol} `
        return symbol;
    }
}