@ccclass('AutoAdaptSprite')
export class AutoAdaptSprite extends Component {
    // [1]
    // dummy = '';

    // [2]
    // @property
    // serializableDummy = 0;

    start() {
        // [3]
    }
    onLoad(){
        view.setResizeCallback(this.onResize.bind(this));
        this.onResize();

    }
    onDestroy(){
        
    }
    onResize(){
        if(!this.node){
            return;
        }
        let screenWidth = View.instance.getVisibleSize().width;
        let designWidth = View.instance.getDesignResolutionSize().width;
        let ratio = parseFloat((screenWidth/designWidth).toFixed(2));
        LogUtil.debug("ratio:"+ratio);
        this.node.setScale(v3(ratio,ratio,1));
    }

    // update (deltaTime: number) {
    //     // [4]
    // }
}

