import { GameUtils } from "../common/utils/GameUtil";
import { Svr30Data } from "./SvrData";

export class User {

    public userId: number = 0;
    public token: any = undefined;
    public password: string = '';

    /** 1陪玩账号 */
    public vistor: number = 0;
    public isWhite: boolean = false;;
    public isGuest: boolean = false;
    /** 停服信息 */
    public stopServerInfo: Svr30Data;

    private static _instance: User;
    public static get instance(): User {
        if (!this._instance) {
            this._instance = new User();
        }
        return this._instance;
    }

    public init(message: any) {

    }

    /**停服开始时间字符串 */
    public get stopServerStart() {
        if (!this.stopServerInfo) {
            return "";
        }
        let date = new Date(this.stopServerInfo.starttime * 1000);
        let startTime = `${GameUtils.formatNumToLen(
            date.getHours(),
            2
        )}:${GameUtils.formatNumToLen(date.getMinutes(), 2)}`;
        return startTime;
    }

    /**停服结束时间字符串 */
    public get stopServerEnd() {
        if (!this.stopServerInfo) {
            return "";
        }
        let date = new Date(this.stopServerInfo.endtime * 1000);
        let endTime = `${GameUtils.formatNumToLen(
            date.getHours(),
            2
        )}:${GameUtils.formatNumToLen(date.getMinutes(), 2)}`;
        return endTime;
    }
}