@ccclass('DropDownList')
@executeInEditMode
export class DropDownList extends Component {

    @property({ displayName: "bgNode", type: Node, tooltip: "弹窗背景，不赋值则无背景" })
    bgNode: Node = null!;
    @property({ displayName: "上方节点", type: Node })
    topNode: Node = null!;
    @property({ displayName: "上方节点箭头", type: Node })
    arrow: Node = null!;

    @property({ displayName: "列表节点", type: Node })
    listNode: Node = null!;
    @property({ displayName: "选中展示的label", type: Label })
    showLabel: Label = null!;

    @property({ displayName: "item", type: Node })
    itemTemp: Node = null!;

    numberList: Array<string> = [];
    itemArr: Array<Node> = [];

    curNum = "";
    curIndex = -1;
    start() {
        // [3]
        if (!EDITOR) {
            this.bindEvents();
        }
    }

    initList(numberList: Array<string> = []) {
        this.removeList();
        this.numberList = numberList;
        for (let i = 0; i < numberList.length; i++) {
            let num = numberList[i];
            let item = instantiate(this.itemTemp);
            item.parent = this.itemTemp.parent;
            item.active = true;
            item.getChildByName("Label")!.getComponent(Label)!.string = num.toString();
            this.itemArr.push(item);
            item.on(Node.EventType.TOUCH_END, this.itemClick, this);
        }
    }

    itemClick(event: EventTouch) {
        let curTarget = event.getCurrentTarget();
        this.selectItem(curTarget);

        this.setListNodeVisible(false);

    }
    selectItem(item: Node) {
        let index = this.itemArr.indexOf(item);
        if (index == -1) {
            return;
        }
        let num = this.numberList[index];
        this.curNum = num;
        this.curIndex = index;
        this.showLabel.string = this.curNum;
    }

    removeList() {
        for (let i = 0; i < this.itemArr.length; i++) {
            this.itemArr[i].destroy();
        }
        this.itemArr = [];
        this.numberList = [];
    }
    bindEvents() {
        this.topNode.on(Node.EventType.TOUCH_END, () => {
            let isVisible = !this.listNode.active;
            this.setListNodeVisible(isVisible);
            // this.listNode.active = !this.listNode.active;
            // if (this.listNode.active == true) {
            //     this.arrow.setRotationFromEuler(v3(0, 0, 180));
            // } else {
            //     this.arrow.setRotationFromEuler(v3(0, 0, 0));
            // }
        }, this)
    }

    private onBg(evt: Event): void {
        this.setListNodeVisible(false);
    }

    setListNodeVisible(isVisible: boolean) {
        this.listNode.active = isVisible;
        if (this.bgNode) {
            this.bgNode.active = isVisible;
            if (isVisible==true) {
                this.bgNode.on(Node.EventType.TOUCH_END, this.onBg, this);
            }
            else
            {
                this.bgNode.off(Node.EventType.TOUCH_END, this.onBg, this);
            }
        }
        if (this.listNode.active == true) {
            this.arrow.setRotationFromEuler(v3(0, 0, 180));
        } else {
            this.arrow.setRotationFromEuler(v3(0, 0, 0));
        }
    }

    // update (deltaTime: number) {
    //     // [4]
    // }
}

