export default class NumberUtil {
    /**
     * 随机一个整数[n,m)
     */
    public static randomIntN(n: number, m: number): number {
        return parseInt(NumberUtil.number2str(Math.random() * (m - n) + n), 10);
    }
    /**
     * 随机一个整数(n,m]
     */
    public static randomintM(n: number, m: number): number {
        return Math.floor(Math.random() * (m - n) + n) + 1;
    }

    public static number2str(num: number): string {
        return <string>(<any>num);
    }

    /** 区间随机，必须传整数 */
    public static randomInt(min: number, max: number): number {
        let diff = max - min + 0.99;
        let res = Math.random() * diff;

        return min + Math.floor(res);
    }

    static randomFloat = (min: number, max: number) => {
        return min + (max - min) * Math.random();
    };
    static randomInteger = (min: number, max: number) => {
        return Math.round(NumberUtil.randomFloat(min, max));
    };

    /**
     * 权重概率数组随机
     * @param array number类型，可整形可浮点型
     * @returns 返回数组下标
     */
    static randByWeight = (array: Array<number>): number => {
        let totalWeight: number = 0;
        let randIndex: number = -1;
        array.forEach((element) => {
            totalWeight += element;
        });

        if (totalWeight <= 0) {
            randIndex = -1;
            return randIndex;
        } else {
            let randVal: number = NumberUtil.randomFloat(0, totalWeight);

            for (let index = 0; index < array.length; index++) {
                const element = array[index];
                if (randVal <= element) {
                    randIndex = index;
                    break;
                } else {
                    randVal -= element;
                }
            }
        }
        return randIndex;
    };

    public static hitRate(rate: number): boolean {
        return Math.random() < rate;
    }

    public static randomNumFromArray(numbers: number[]): number {
        let index = this.randomInt(0, numbers.length - 1);
        return numbers[index];
    }

    public static trimFloat(value: number, precision: number = 2): string {
        return value.toFixed(2);
    }

    //转换成易读数量
    public static toHNumber(value: number): string {
        if (value >= 100000000) {
            return (value / 100000000).toFixed(2) + "亿";
        } else if (value >= 100000) {
            let point = 0;
            let dev = value / 10000 - Math.floor(value / 10000);
            let temp = Math.floor(dev * 100);
            if (temp > 0) {
                point = 2;
                if (Math.floor(temp / 10) <= 0) {
                    point = 1;
                }
            }
            return (value / 10000).toFixed(point) + "万";
        }

        return String(value);
    }
}
