import { BlockInputEvents, Node, UITransform, screen, game, isValid } from "cc";
import { NetErrCode } from "../../common/define/StatisticsDefine";
import ComponentMgr from "../../mgr/ComponentMgr";
import { NoticeParam } from "../../view/ui/UIAlert";
import { StatisticsManager } from "../../mgr/StatisticsManager";
import { UIID } from "./UIDefined";
import { UIManager } from "./UIManager";
import i18n from "../language/i18n";
import { UIPopupView } from "./UIPopupView";
import { GameModel } from "../../main/GameModel";

/**
 * ui工具类
 */
export default class UIUtils {
    /**
     * 添加全屏触摸屏蔽
     * @param parent
     */
    static addMaskLayer(parent: Node) {
        let node = new Node();
        node.name = "mask";
        node.parent = parent;
        node.addComponent(UITransform).setContentSize(screen.windowSize);
        node.addComponent(BlockInputEvents);
    }

    /**
     * 移除全屏触摸屏蔽
     * @param parent
     * @returns
     */
    static removeMaskLayer(parent: Node) {
        if (!parent) return;
        let mask = parent.getChildByName("mask");
        if (mask) mask.destroy();
    }

    static showLoading() {
        let view = UIManager.getInstance().getUI(UIID.UILoadingView);
        if (!isValid(view)) {
            UIManager.getInstance().open(UIID.UILoadingView);
        } else {
            view.node.active = true;
        }
    }

    static showTips(tips: string) {
        ComponentMgr.showTips(tips);
    }

    static showTipsById(id: number) {
        ComponentMgr.showTipsById(id);
    }

    /**
     * 隐藏loading
     */
    static hideLoading() {
        UIManager.getInstance().closeToUI(UIID.UILoadingView);
    }

    /**
     * 网络连接失败提示
     * @param cb 
     */
    static netErrorTips(errCode?: number, cb?: Function) {
        errCode = errCode ?? NetErrCode.system;
        let param: NoticeParam = {
            content: i18n.tr(1001030, errCode),
            okName: i18n.tr(2001011),
            singleBtn: true,
            okFunc: cb
        };
        UIManager.getInstance().open(UIID.UIAlert, param);
        StatisticsManager.getInstance().loginReport(errCode);
    }

    static closeTips() {
        if (UIManager.getInstance().isTopUI(UIID.UIAlert)) {
            UIManager.getInstance().closeToUI(UIID.UIAlert);
        }
    }

    /**
     * 显示错误码提示
     * @param code 错误码id
     * @param args 替换参数
     */
    static showPopupView(code: number, args?: any) {
        UIUtils.hideLoading();
        let popupData: any = GameModel.getInstance().getPopupDataById(code);
        if (!popupData) {
            return;
        }
        let popupView: UIPopupView = UIManager.getInstance().getUI(UIID.UIPopup) as UIPopupView;
        if (!popupView) {
            UIManager.getInstance().open(UIID.UIPopup, { code: code, args: args });
        }
        else {
            popupView.setPopupData(code, args);
        }
    }

    /**显示错误码 */
    static showError(proto, code) {
        code = parseInt(code);
        if (code == null || isNaN(code) || code < 1 || code == 23 || code == 25) {
            return;
        }
        if (code != 13) {
            let langCode = 110000 + code;
            let content = i18n.tr(langCode) || `message error! proto: + ${proto},` + 'code:' + langCode;
            if (!content || content == "") {
                return;
            }
            UIUtils.showTips(content);
        }
    }
}
