
import { js, sys } from "cc";
import { ProtoUtil } from "../../common/utils/ProtoUtil";
import { Eventer } from "../Eventer";
import { Events } from "../Events";
import { Singleton } from "../Singleton";
import { HttpReq } from "./HttpReq";

export type HttpFailCallback<RequestData, RespondData, Listener> = (request: HttpRequest<RequestData, RespondData, Listener>) => void;
export type HttpRequestCallback<RespondData> = (data: RespondData) => void;

class HttpRequestParams<RequestData>{
    data: RequestData = null!;
    constructor(data: RequestData) {
        js.mixin(this, HttpManager.getInstance().reqParam);
        this.data = data
    }
}

export class HttpRespondParams<RespondData>{
    data: RespondData = null!;
    desc: string = "";
    errcode: number = 0;
    msg: string = "";
    time: number = 0;
}


export class HttpRequest<RequestData, RespondData, Listener> {
    public path: string = null!;
    public url: string = null!;
    public params: HttpRequestParams<RequestData> = null!;
    public listener: Listener = null!;
    public callback: HttpRequestCallback<RespondData> = null!;
    public fails: number = 0;
    public failCallback?: HttpFailCallback<RequestData, RespondData, Listener> = null!;
    constructor(
        listener: Listener,
        path: string,
        params: RequestData,
        callback: HttpRequestCallback<RespondData>,
        failCallback?: HttpFailCallback<RequestData, RespondData, Listener>,
        url?: string
    ) {
        this.listener = listener;
        this.path = path;
        this.params = new HttpRequestParams(params);
        this.callback = callback;
        this.failCallback = failCallback;
        this.url = url!;
    }
}

export enum HttpRespondErrorCode {
    OK = 0,
}

export interface HttpRespond<HttpRespondType> {
    errcode: HttpRespondErrorCode;
    data: HttpRespondType;
}

export class HttpManager extends Singleton<HttpManager>() {
    public static CONTENT_TYPE = 'application/x-www-form-urlencoded;charset=utf-8';//'application/json';
    public reqParam: any;

    /**
     * 初始化请求参数
     * @param param 
     */
    public initParam(reqParam?: any) {
        this.reqParam = reqParam;
    }
}