import { native, sys } from "cc";
import { APP_TYPE, StatisticsDownloadType, StatisticsEvent, StatisticsStatus, StatisticsType } from "../common/define/EnumDefine";
import { HttpMgr } from "../common/net/http/HttpMgr";
import { HttpReqPack } from "../common/net/http/HttpReqPack";
import { HttpRespPack } from "../common/net/http/HttpRespPack";
import NativeApi from "../common/sdk/NativeApi";
import { Global } from "../main/Global";
import { User } from "../model/User";
import { Singleton } from "../framework/Singleton";
import { UIID } from "../framework/ui/UIDefined";
import { UIManager } from "../framework/ui/UIManager";

export class StatisticsManager extends Singleton<StatisticsManager>() {

    /**开始时间 */
    private startTimes: number[] = [];

    init() {
        // this.catchError();
    }

    setStartTime(type: number) {
        if (this.startTimes[type]) {
            console.log(">>>>>>>>>>>>>>>>>>>>>>type : " + type);
        }
        this.startTimes[type] = new Date().getTime();
    }

    /**
     * @return 秒
     */
    getTimesByType(type: number) {
        let startime = this.startTimes[type];
        if (!startime) {
            return 0;
        }
        this.startTimes[type] = 0;
        return new Date().getTime() - startime;
    }

    public eventTrig(id: StatisticsEvent, data?: any): void {
        if (!sys.isNative) {
            return;
        }
        switch (id) {
            // 加载资源时间 9
            case StatisticsEvent.LOADED_RES_START:
                this.setStartTime(id << 8);
                this.loadedRes(StatisticsStatus.START);
                break;
            case StatisticsEvent.LOADED_RES_SUCCESS:
                this.setStartTime(id << 8);
                this.loadedRes(StatisticsStatus.SUCCESS);
                break;
            case StatisticsEvent.LOADED_RES_FAIL:
                this.setStartTime(id << 8);
                this.loadedRes(StatisticsStatus.FAIL);
                break;
            // 获取登录配置时间 5
            case StatisticsEvent.LOADED_CONFIG_SUCCESS:
                this.getConfig(StatisticsStatus.SUCCESS);
                break;
            case StatisticsEvent.LOADED_CONFIG_FAIL:
                this.getConfig(StatisticsStatus.FAIL);
                break;
            // 大厅请求协议 7
            case StatisticsEvent.GET_REQUEST_SUCCESS:
                this.getRequest(StatisticsStatus.SUCCESS);
                break;
            case StatisticsEvent.GET_REQUEST_FAIL:
                this.getRequest(StatisticsStatus.FAIL);
                break;
            // 下载游戏的时间
            case StatisticsEvent.FINISH_DOWNLOAD_GAME:
                this.downloadGame(data.id, StatisticsDownloadType.DOWNLOAD, data.status);
                break;
            case StatisticsEvent.CANCEL_DOWNLOAD_GAME:
                this.downloadGame(data.id, StatisticsDownloadType.CANCEL);
                break;
            case StatisticsEvent.Refresh_DOWNLOAD_GAME:
                this.downloadGame(data.id, StatisticsDownloadType.REFRESH);
                break;
            default:
                this.setStartTime(id << 8);
                break;
        }
    }

    /**
     * 登录打点
     * @param type
     * @param needTimes
     * @param errCode
     */
    loginReport(type: number, needTimes?: boolean) {
        //后台无该接口
        return;
        let times = 0;
        if (needTimes) {
            if (this.startTimes[type] && this.startTimes[type] > 0) {
                times = new Date().getTime() - this.startTimes[type];
                this.startTimes[type] = 0;
            }
            if (times == 0) return;
        }
        times = times > 0 ? times : 0;
        let pack = HttpReqPack.create("/api/dot/cocosLogin", {
            type: type,
            num: 1,
            times: times,
        });
        HttpMgr.Instance().send(pack);
    }

    /**
     * 异常捕获上报
     */
    catchError() {
        let _this = this;
        if (sys.isBrowser) {
            window.onerror = function (
                event: Event | string,
                source?: string,
                lineno?: number,
                colno?: number,
                err?: Error
            ) {
                if (err) {
                    _this.errorReport(`${err.message}${err.stack}`);
                }
            };
        } else if (sys.isNative) {
            window["__errorHandler"] = function (...args) {
                if (args) {
                    _this.errorReport(`${args.toString()}`);
                }
            };
        }
    }

    /**
     * 异常上报
     * @param errMsg
     */
    errorReport(errMsg: string) {
        if (Global.debug)
            UIManager.getInstance().open(UIID.UIErrorAlert, errMsg);
        let pack = HttpReqPack.create("/api/Game/reportJsError", {
            content: errMsg,
        });
        HttpMgr.Instance().send(
            pack,
            null,
            (msg: HttpRespPack, userdata: any) => { },
            null
        );
        NativeApi.recordException(errMsg);
    }

    /**
     * 平台登录过程时长上报
     * @param onResp
     * @param thisArg
     * @param userData
     */
    private appReport(time_diff: number, event: number, status: number) {
        let json = {
            client_info: [{
                time_diff: time_diff,
                event: event,
                status: status,
                ctime: Math.floor(Date.now() / 1000),
                app_type: APP_TYPE.cocos
            }]
        };
        let pack = HttpReqPack.create("/api/LoginProc/timeDiff?action=appReport", JSON.stringify(json));
        HttpMgr.Instance().send(pack);
    }

    /**
     * 请求登陆配置时间
     */
    private getConfig(status: StatisticsStatus) {
        let time_diff = this.getTimesByType(StatisticsEvent.LOADED_CONFIG_START << 8);
        if (status == StatisticsStatus.SUCCESS && (time_diff <= 0 || time_diff >= 7200000)) {
            return;
        }
        this.appReport(time_diff, StatisticsType.LOGIN_CONFIG, status);
    }

    /** 请求登录后协议的时间 */
    private getRequest(status: StatisticsStatus) {
        let time_diff = this.getTimesByType(StatisticsEvent.GET_REQUEST_START << 8);
        if (status == StatisticsStatus.SUCCESS && (time_diff <= 0 || time_diff >= 7200000)) {
            return;
        }
        this.appReport(time_diff, StatisticsType.GET_REQUEST, status);
    }

    /** 登录成功后加载资源的时间 */
    private loadedRes(status: StatisticsStatus) {
        let time_diff = this.getTimesByType(StatisticsEvent.LOADED_RES_START << 8);
        if (status == StatisticsStatus.SUCCESS && (time_diff <= 0 || time_diff >= 7200000)) {
            return;
        }
        this.appReport(time_diff, StatisticsType.LOADED_RES, status);
    }

    /**
     * 游戏登录过程时长上报
     * @param onResp
     * @param thisArg
     * @param userData
     */
    private gameReport(game_id: number, time_diff: number, event: number, status: number) {
        let json = {
            client_info: [{
                game_id: game_id,
                uid: User.instance.userId,
                time_diff: time_diff,
                event: event,
                status: status,
                ctime: Math.floor(Date.now() / 1000),
                app_type: APP_TYPE.cocos
            }]
        };
        let pack = HttpReqPack.create("/api/LoginProc/timeDiff?action=clientReport", JSON.stringify(json));
        HttpMgr.Instance().send(pack);
    }

    /** 
     * 下载游戏的时间 
     */
    private downloadGame(id: number, type: StatisticsDownloadType, status: StatisticsStatus = StatisticsStatus.SUCCESS) {
        let time_diff = this.getTimesByType(StatisticsEvent.DOWNLOAD_GAME << 8);
        if (time_diff <= 0 || time_diff >= 7200000) {
            return;
        }
        this.gameReport(id, time_diff, type, status);
    }

    /**
     * 客户端断线统计上报
     * @param onResp
     * @param thisArg
     * @param userData
     */
    public static clientReport(game_id: number, drop_type: number) {
        let json = {
            "client_info": [{
                "game_id": game_id,
                "uid": User.instance.userId,
                "plat_type": "app",
                "drop_type": drop_type,
                "drop_param": "",
                "ctime": Global.svrTimeS
            }]
        };
        let pack = HttpReqPack.create("/api/NmMsg/dropRate?action=clientReport", JSON.stringify(json));
        HttpMgr.Instance().send(pack)
    }
}

export function eventTrig(id: StatisticsEvent, data?: any): void {
    StatisticsManager.getInstance().eventTrig(id, data);
}   
