import { Button, Component, Prefab, EditBox, Node, sys, _decorator, instantiate, director, ToggleContainer, Toggle, NodeEventType, View } from "cc";
import WebMsgHandler, { WebSrc } from "../common/net/http/WebMsgHandler";
import { EntryManager } from "../framework/hall/entry/EntryManager";
import { UILayer } from "../framework/ui/UILayer";
import { UIManager } from "../framework/ui/UIManager";
import { Global } from "../main/Global";
const { ccclass, property } = _decorator;

@ccclass('GameTestEnterScene')
export class GameTestEnterScene extends Component {

    @property({
        type: EditBox,
        displayName: '服务器输入'
    })
    serverEdit: Node;

    @property({
        type: EditBox,
        displayName: '余额输入'
    })
    moneyEdit: Node;

    @property({
        type: ToggleContainer,
        displayName: '币种输入'
    })
    moneyTypeToggle: ToggleContainer;

    @property({
        type: EditBox,
        displayName: '玩家id输入'
    })
    idEdit: Node;

    @property({
        type: EditBox,
        displayName: '游戏id输入'
    })
    gameIdEdit: Node;

    @property({
        type: ToggleContainer,
        displayName: '语种输入'
    })
    langTypeToggle: ToggleContainer;

    @property({
        type: Button,
        displayName: '登录按钮'
    })
    loginBtn: Button;

    @property(Prefab)
    uiLayer: Prefab = null;

    onLoad() {
        this.addUILayer();

    }

    addUILayer() {
        let uiLayer = UIManager.getInstance().uiLayer as UILayer;
        if (!uiLayer) {
            let node = instantiate(this.uiLayer);
            director.addPersistRootNode(node);
        }
    }

    private offEvent(): void {
        //移除输入框屏幕尺寸监听
        let editb = this.serverEdit.getComponent(EditBox)
        //Log.d("offEvent", editb["_impl"], editb["_impl"]["_resize"], editb.node.hasEventListener(NodeEventType.SIZE_CHANGED))
        View.instance.off('canvas-resize', editb["_impl"]["_resize"], editb["_impl"])
        editb = this.moneyEdit.getComponent(EditBox)
        View.instance.off('canvas-resize', editb["_impl"]["_resize"], editb["_impl"])
        editb = this.idEdit.getComponent(EditBox)
        View.instance.off('canvas-resize', editb["_impl"]["_resize"], editb["_impl"])
        editb = this.gameIdEdit.getComponent(EditBox)
        View.instance.off('canvas-resize', editb["_impl"]["_resize"], editb["_impl"])
        //Log.d("offEvent 000 ", View.instance.hasEventListener('canvas-resize', editb["_impl"]["_resize"]))
    }

    start() {
        this.loginBtn.node.on(Node.EventType.TOUCH_START, this.login, this);

        //缓存
        this.gameIdEdit.getComponent(EditBox).string = sys.localStorage.getItem('gameId') || '';
        this.idEdit.getComponent(EditBox).string = sys.localStorage.getItem('uid') || '';
        this.moneyEdit.getComponent(EditBox).string = sys.localStorage.getItem('money') || '';
        this.serverEdit.getComponent(EditBox).string = sys.localStorage.getItem('server') || '';
    }

    private login() {
        let gameId = this.gameIdEdit.getComponent(EditBox).string,
            uid = this.idEdit.getComponent(EditBox).string,
            money = this.moneyEdit.getComponent(EditBox).string,
            server = this.serverEdit.getComponent(EditBox).string,
            env = 1,
            lang = this.lang,
            moneyType = this.currency,
            homeUrl = '';


        //本地保存
        sys.localStorage.setItem('gameId', gameId);
        sys.localStorage.setItem('uid', uid);
        sys.localStorage.setItem('money', money);
        sys.localStorage.setItem('server', server);



        let path = `serverDebug=${server}&money=${money}&moneyType=${moneyType}&currency=${moneyType}&id=${gameId}&uid=${uid}&homeUrl=${homeUrl}&lang=${lang}&env=${env}`;
        WebMsgHandler.webSrc = new WebSrc(path);

        this.offEvent()
        director.loadScene("GameEnterScene", function (err, scene) {
            // if (!err) director.runScene(scene);

        });


        // LoadingManager.getInstance().loadInitConfig(this.enterGame.bind(this));

        // I18n.getInstance().init();
        // ComponentMgr.getInstance().init();
        // EntryManager.getInstance().init();
    }

    private get lang(): string {
        for (let key in this.langTypeToggle.toggleItems) {
            let item = this.langTypeToggle.toggleItems[key];
            if (item.isChecked)
                return item.node.name;
        }
        return 'en';

    }

    private get currency(): string {
        for (let key in this.moneyTypeToggle.toggleItems) {
            let item = this.moneyTypeToggle.toggleItems[key];
            if (item.isChecked)
                return item.node.name;
        }
        return 'USD';
    }

    private enterGame() {
        console.log("GameEnterScene enterGame==============");
        // AudioManager.Instance().stopMusic();
        EntryManager.getInstance().loadCommonConfig(Global.gameId.toString());
        EntryManager.getInstance().enterGame(Global.gameId.toString());
    }
}