import { _decorator, Component, Node } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('WithDrawCtrl')
export class WithDrawCtrl {
    private static _instance: WithDrawCtrl = null!;
    public static get instance():WithDrawCtrl 
    { 
        if(!this._instance)
        {
            this._instance = new WithDrawCtrl();
        }
        return this._instance;
    }
    public selBankCardIdx:number=0;
}

