import { _decorator, v3, Vec3 } from 'cc';
const { ccclass, property } = _decorator;

export interface BezierCtrlP2 {
    controlPos0: Vec3;
    controlPos1: Vec3;
}

@ccclass('EffectsUtil')
export class EffectsUtil{

    /**
     * 通过起点和终点坐标，获取三阶贝塞尔曲线的两个控制点坐标（s行曲线），具体效果：参考货币获取特效
     * @author ice
     * @param mStartPoint 起点坐标
     * @param mEendPoint 终点坐标
     * @returns BezierCtrlP2 两个控制点的坐标
     */
    public static get2BezierCtrlP(mStartPoint:Vec3,mEendPoint:Vec3):BezierCtrlP2
    {
        let distance:number= Math.sqrt(Math.pow(mEendPoint.x - mStartPoint.x, 2) +Math.pow(mEendPoint.y - mStartPoint.y, 2));
        let myRadius:number=distance>>2;
        let distance_x:number=mEendPoint.x - mStartPoint.x;
        let distance_y:number=mEendPoint.y - mStartPoint.y;
        let pointC_x:number = mStartPoint.x + (distance_x>>2) ;
        let pointC_y:number = mStartPoint.y + (distance_y>>2);
        let myRadians: number = Math.atan2(pointC_y, pointC_x);
        myRadians = myRadians + (Math.PI / 180) * 270;
        let controlPosX0 = pointC_x+Math.cos(myRadians)*myRadius;
        let controlPosY0 = pointC_y+Math.sin(myRadians)*myRadius;
        let pointD_x:number = mStartPoint.x + (distance_x>>2)*3 ;
        let pointD_y:number = mStartPoint.y + (distance_y>>2)*3;
        myRadians = Math.atan2(pointD_y, pointD_x);
        myRadians = myRadians + (Math.PI / 180) * 90;
        let controlPosX1 = pointD_x+Math.cos(myRadians)* myRadius;
        let controlPosY1 = pointD_y+Math.sin(myRadians)* myRadius;
        return {controlPos0:v3(controlPosX0,controlPosY0),controlPos1:v3(controlPosX1,controlPosY1)};
    }

    /**
     * 三阶贝塞尔曲线
     * @param t 时间
     * @param p1 
     * @param c1 
     * @param c2 
     * @param p2 
     * @returns 
     */
    public static threeBezier (t: any, p1: any, c1: any, c2: any, p2: any)
     {
        let x =
            p1.x * (1 - t) * (1 - t) * (1 - t) +
            3 * c1.x * t * (1 - t) * (1 - t) +
            3 * c2.x * t * t * (1 - t) +
            p2.x * t * t * t;
        let y =
            p1.y * (1 - t) * (1 - t) * (1 - t) +
            3 * c1.y * t * (1 - t) * (1 - t) +
            3 * c2.y * t * t * (1 - t) +
            p2.y * t * t * t;
        return v3(x, y, 0);
    }

    /**
     * forthBezier
     * @param t 
     * @param p1 
     * @param c1 
     * @param c2 
     * @param c3 
     * @param p2 
     * @returns 
     */
     public static forthBezier(t: any, p1: any, c1: any, c2: any, c3: any, p2: any)
    {
        let x =
            p1.x * (1 - t) * (1 - t) * (1 - t) * (1 - t) +
            4 * c1.x * t * (1 - t) * (1 - t) * (1 - t) +
            4 * c2.x * t * t * (1 - t) * (1 - t) +
            4 * c3.x * t * t * t * (1 - t) +
            p2.x * t * t * t * t;
        let y =
            p1.y * (1 - t) * (1 - t) * (1 - t) * (1 - t) +
            4 * c1.y * t * (1 - t) * (1 - t) * (1 - t) +
            4 * c2.y * t * t * (1 - t) * (1 - t) +
            4 * c3.y * t * t * t * (1 - t) +
            p2.y * t * t * t * t;
        return v3(x, y, 0);
    }
}

