    // 字符串转UTF8编码
    public static stringToUTF8Bytes(str: string): any[] {
        var utf8 = [];
        for (var i = 0; i < str.length; i++) {
            var charcode = str.charCodeAt(i);
            if (charcode < 0x80) utf8.push(charcode);
            else if (charcode < 0x800) {
                utf8.push(0xc0 | (charcode >> 6),
                    0x80 | (charcode & 0x3f));
            }
            else if (charcode < 0xd800 || charcode >= 0xe000) {
                utf8.push(0xe0 | (charcode >> 12),
                    0x80 | ((charcode >> 6) & 0x3f),
                    0x80 | (charcode & 0x3f));
            }
            // surrogate pair
            else {
                i++;
                // UTF-16 encodes 0x10000-0x10FFFF by
                // subtracting 0x10000 and splitting the
                // 20 bits of 0x0-0xFFFFF into two halves
                charcode = 0x10000 + (((charcode & 0x3ff) << 10)
                    | (str.charCodeAt(i) & 0x3ff))
                utf8.push(0xf0 | (charcode >> 18),
                    0x80 | ((charcode >> 12) & 0x3f),
                    0x80 | ((charcode >> 6) & 0x3f),
                    0x80 | (charcode & 0x3f));
            }
        }
        return utf8;
    }

    // 将Unit8Array转为Array
    public static uint8ArrayToArray(unit8Array: any[]): any[] {
        let array = [];
        for (let i = 0; i < unit8Array.length; i++) {
            array.push(unit8Array[i]);
        }
        return array;
    }


    // UTF8编码转字符串
    public static utf8ArrayToString = function (array: any): string {
        var out, i, len, c;
        var char2, char3;

        out = "";
        len = array.length;
        i = 0;

        while (i < len) {
            c = array[i++];

            switch (c >> 4) {
                case 0: case 1: case 2: case 3: case 4: case 5: case 6: case 7:
                    // 0xxxxxxx
                    out += String.fromCharCode(c);
                    break;
                case 12: case 13:
                    // 110x xxxx   10xx xxxx
                    char2 = array[i++];
                    out += String.fromCharCode(((c & 0x1F) << 6) | (char2 & 0x3F));
                    break;
                case 14:
                    // 1110 xxxx  10xx xxxx  10xx xxxx
                    char2 = array[i++];
                    char3 = array[i++];
                    out += String.fromCharCode(((c & 0x0F) << 12) |
                        ((char2 & 0x3F) << 6) |
                        ((char3 & 0x3F) << 0));
                    break;
            }
        }

        return out;
    }

    public static ParseArrayFromStructString(str: string): Array<number> {
        str = str.substr(1, str.length - 1);
        let splitArray: Array<string> = str.split(",");
        let numArray: Array<number> = [];
        for (let val of splitArray) {
            numArray.push(parseInt(val));
        }

        return numArray;
    }

    public static genRandCode(codeNum: number): string {

        let code = '';
        for (let i = 0; i < codeNum; ++i) {
            code += (i == 0) ? Math.ceil(Math.random() * 8) + 1 : Math.floor(Math.random() * 10);
        }

        return code;
    }

    public static genRandCodeEnglish(codeNum: number) {

        var result = [];
        for (var i = 0; i < codeNum; i++) {
            var ranNum = Math.ceil(Math.random() * 25); //生成一个0到25的数字
            //大写字母'A'的ASCII是65,A~Z的ASCII码就是65 + 0~25;然后调用String.fromCharCode()传入ASCII值返回相应的字符并push进数组里
            result.push(String.fromCharCode(65 + ranNum));
        }
        return result.join('');
    }


    public static isNumber(str: string): boolean {
        if (str.length <= 0) {
            return false;
        }
        for (let val of str) {
            if (val < "0" || val > "9") {
                return false;
            }
        }

        return true;
    }

    /**
    * 从URL中获取域名
    * @param url
    */
    public static getHostFromUrl(url: string): string {
        let reg = RegExp("^((http://)|(https://)|(ws://)|(wss://))?([a-zA-Z0-9]([a-zA-Z0-9\\-\\_]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,6}(?=/)");
        let ret = url.match(reg);
        return ret ? ret[0] : "";
    }
    /** url字符串参数转化成对象 */
    public static getQueryStringArgs(url: string) {
        //保存数据的对象
        let args = {};
        if (!url) {
            return args;
        }
        if (url.indexOf("://") == -1) {
            return args;
        }
        url = decodeURIComponent(url);
        let qs = url.split('://').pop(); //取得查询字符串并去掉开头的://
        //取得每一项
        let items = qs.split("&");
        //逐个将每一项添加到 args 对象中
        for (let i = 0, len = items.length; i < len; i++) {
            let item = items[i].split("=");
            args[item[0]] = item[1];
        }
        return args;
    }

    /**
     * 把一个键值对对象转换成HTTP传输参数格式(key=value&key=value)
     * @param params
     * @returns {string}
     */
    public static parseURLVariablesStr(params: any): string {
        let list = [];
        for (let key in params) {
            list.push(key + "=" + params[key]);
        }
        return list.join("&");
    }
