    /**输出手机号，手机号区域信息 */
    public static checkMobile(mobile: string) {
        for (let v of this.mobileRegular) {
            if (v.Reg.test(mobile)) {
                return {
                    Area: v.Area,
                    AreaAbb: v.AreaAbb
                }
            }
        }
        return null;
    }

    /**账号规则(7~20位数字，字母或者数字与字母组合) */
    public static checkAccount(account: string) {
        let reg1 = /^[0-9]{7,20}$/;
        let reg2 = /^[A-z]{7,20}$/;
        let reg3 = /^(?![A-z]+$)(?![0-9]+$)[A-z0-9]{7,20}$/;

        return reg1.test(account) || reg2.test(account) || reg3.test(account);
    }

    /**检测密码规则(6~16位数字与字母组合) */
    public static checkPassWord(passwd: string) {
        let reg = /^(?![A-z]+$)(?![0-9]+$)[A-z0-9]{6,16}$/;

        return reg.test(passwd);
    }

    /**检测是否全是数字*/
    public static checkNum(str: string) {
        str = str.replace(",", "");
        let reg = /^-?\d+(\.\d+)?$/;
        return reg.test(str);
    }

    /**格式化千分位逗号数字*/
    public static numStrToNum(str: string): string {
        // str = str.replace(",", "");
        str = str.replace(/,/g, "");
        return str;
    }


    /**检测是否全是数字字符 */
    public static checkNumChar(str: string) {
        let reg = /^[0-9]+$/;
        return reg.test(str);
    }

    /**提取字符串中的所有数字字符 */
    public static getNumChar(str: string) {
        let reg = /[^0-9 | \.]+/g;
        let value = str.replace(reg, "");
        return value;
    }

    /**
     * 检查email是否合法
     * @param str
     */
    public static checkEmail(str: string) {
        let reg = new RegExp("^[a-z0-9]+([._\\-]*[a-z0-9])*@([a-z0-9]+[-a-z0-9]*[a-z0-9]+.){1,63}[a-z0-9]+$"); //正则表达式
        return reg.test(str);
    }
    /**格式化时间
     * @param time 时长 s
     */
    public static formatTime(time: number, format: string = "hh:mm:ss") {
        let t = time;
        let hour = Math.floor(t / 3600);
        t = t - hour * 3600;
        let minute = Math.floor(t / 60);
        t = t - minute * 60;
        let second = Math.floor(t);

        let info: any = {
            "h+": hour,
            "m+": minute,
            "s+": second,
        };

        for (let key in info) {
            if (new RegExp("(" + key + ")").test(format)) {
                format = format.replace(RegExp.$1, RegExp.$1.length == 1 ?
                    info[key] : ("00" + info[key]).substr(("" + info[key]).length));
            }
        }
        return format;
    }

    /**
     * 解决两个数相乘精度丢失问题
     */
    public static floatMul(a, b) {
        var c = 0,
            d = a.toString(),
            e = b.toString();
        try {
            c += d.split(".")[1].length;
        } catch (f) { }
        try {
            c += e.split(".")[1].length;
        } catch (f) { }
        return Number(d.replace(".", "")) * Number(e.replace(".", "")) / Math.pow(10, c);
    }

    /**
     * 解决两个数相除精度丢失问题
     */
    public static floatDiv(a, b) {
        var c, d, e = 0,
            f = 0;
        try {
            e = a.toString().split(".")[1].length;
        } catch (g) { }
        try {
            f = b.toString().split(".")[1].length;
        } catch (g) { }
        return c = Number(a.toString().replace(".", "")), d = Number(b.toString().replace(".", "")), StringUtil.floatMul(c / d, Math.pow(10, f - e));
    }
    /**
     * 精度合成字符串
     * @param precision 精度
     */
    private static createZeroPrecision(precision: number): string {
        let str = precision > 0 ? "0." : "0";
        for (let i = 0; i < precision; i++) {
            str += "0";
        }
        return str;
    }
    /**
    * 千分位格式化整数
    * @param val
    */
    private static formatDigitByTHS(val: number | string): string {
        val = val + "";
        let reg = /(\d)(?=(?:\d{3})+$)/g;
        val = val.replace(reg, "$1,");
        return val;
    }

    /**
     * 修改数字精度
     * @param score
     */
    private static fixedDigital(score: number): number {
        let num = Math.floor(score);
        if (score >= 1) {
            score = score - num;
        }
        let fixed = Math.pow(10, Global.point + 1);
        score = num + (score * fixed / 10 >> 0) * 10 / fixed;
        return score;
    }

    /**
     * 合成格式化字符串
     * @param pre 整数部份
     * @param decimal 小数部份
     * @param precision 精度
     */
    private static formateNumToStr(pre: string, decimal: string, precision: number) {
        let str = precision > 0 ? pre + "." : pre;
        decimal = decimal ? decimal.split(".")[1] || "" : "";
        for (let i = 0; i < precision; i++) {
            str = str + (decimal[i] || "0");
        }
        return str;
    }
    /*
   * formatMoney(s,type)
   * 功能：金额按千位逗号分割
   * 参数：s，需要格式化的金额数值.
   * 返回：返回格式化后的数值字符串.
   */
    public static formatMoney(money: string | number): string {
        let point = Global.point;
        let ths = Global.thousandPoint;
        money = money + "";
        if (!StringUtil.checkNum(money)) {
            return StringUtil.createZeroPrecision(point);
        }
        let numArr = money.split(".");
        let integer = ths ? StringUtil.formatDigitByTHS(numArr[0]) : numArr[0];
        let decimal = StringUtil.fixedDigital(Number("0." + (numArr[1] || "0"))) + "";
        let str = StringUtil.formateNumToStr(integer, decimal, point);
        return str;
    }
    /**格式化字符串
     * 替换字符串中的占位符{0} 从0开始
     */
    public static formatString(str: string, ...parms: any[]): string {
        if (!str) {
            return "";
        }

        let result = str;
        if (parms && parms.length > 0) {
            for (let i: number = 0; i < parms.length; i++) {
                let replaceStr: RegExp = new RegExp(`\\{${i}\\}`, "g");
                let tempStr: string = parms[i];
                result = result.replace(replaceStr, tempStr);
            }
        }
        return result;
    }

    /**多语言文本参数注入 */
    // public static formatLanguageString (str: string, ...params: string[]) {
    public static formatLanguageString(str: string, params: string[]) {
        let _str = str.concat();
        for (let i = 0; i < params.length; i++) {
            let mark = "%" + (i + 1).toString();
            while (_str.indexOf(mark) != -1) {
                _str = _str.replace(mark, params[i])
            }
        }
        return _str;
    }

    public static replaceUid(text: string, start: number = 4, end: number = 7): string {
        let str = '';
        end = text.length < end ? text.length : end;
        if (text) {
            let slice1: string = text.slice(0, start);
            let slice2: string = text.slice(end);
            let count = end - start;
            count = count > 0 ? count : 0;
            let replace = '';
            for (let i = 0; i < count; i++) {
                replace += '*'
            }
            str = slice1 + replace + slice2;
        }
        return str;
    }

    /** 
     * string模糊化
     * @description 前三位为*号，只显示string的后3位
     */
    public static blurrStr(str: string): string {
        return `***${str.substring(str.length - 3)}`;
    }
