import { _decorator, Component, Node, Animation, Label } from "cc";
import AudioManager from "../../framework/manager/AudioManager";
import { SoundDefine } from "../define/ResDefine";
import { Eventer } from "../../framework/Eventer";
import { Events } from "../../framework/Events";
import { Global } from "../../main/Global";
import { ScreenType } from "../../framework/ui/UIView";
const { ccclass, property } = _decorator;

@ccclass("Tips")
export class Tips extends Component {
    @property({ displayName: "内容", type: Node })
    content: Node = null!;
    @property({ displayName: "label", type: Label })
    label: Label = null!;
    @property({ displayName: "bg", type: Node })
    bg: Node = null!;

    start() {
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
        if (Global.gameScreenType == ScreenType.Portrait) {
            this.content.getComponent(Animation)?.play("tips_ver_ani");
        } else {
            this.content.getComponent(Animation)?.play("tips_ani");
        }
        this.content
            .getComponent(Animation)
            ?.on(Animation.EventType.FINISHED, () => {
                this.node.destroy();
            });
        this.changeScreen();
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
    }

    initTips(str: string) {
        this.label.string = str;
        AudioManager.Instance().playEffect(SoundDefine.sound_error);
    }

    private changeScreen(): void {
        let contentNode: Node = this.node.getChildByName("content");
        if (Global.gameScreenType == ScreenType.Portrait) {
            contentNode.angle = 0;
        } else {
            contentNode.angle = 0;
        }
    }
}
