/**
 * 多播委托
 */
export class Delegate {

    public init(...args:any[]): void {
    }

    protected delegateDataArr: Array<DelegateData> = [];
    /** 函数总数 */
    public get count(): number {
        return this.delegateDataArr.length;
    }
    /**
     * 是否存在参数目标函数。
     * @param fun 目标函数。
     * @return 存在?
     */
    public has(fun: Function, thisArg: any): boolean {
        let len = this.delegateDataArr.length;
        while (len --) {
            let item = this.delegateDataArr[len];
            if(item.fun === fun && item.thisObj === thisArg) {
                return true;
            }
        }
        return false;
    }
    /**
     * 注册函数。
     * @param fun 目标函数。
     * @param thisArg This指针。
     */
    public register(fun: Function, thisArg: any): void {
        if (this.has(fun, thisArg)) {
            return;
        }
        let data = new DelegateData();
        data.fun = fun;
        data.thisObj = thisArg;
        this.delegateDataArr.push(data);
    }
    /**
     * 注销函数。
     * @param fun 目标函数。
     */
    public unregister(fun: Function, thisObj: any): void {  
        if (!this.has(fun, thisObj))
            return;
        let list = this.delegateDataArr;
        for(let i = 0, len = list.length; i < len; i ++) {
            if(list[i].fun === fun && list[i].thisObj == thisObj) {
                this.delegateDataArr.splice(i, 1);
                break;
            }
        }
    }
    /**
     * 清空所有函数。
     */
    public clear(): void {
       this.delegateDataArr.length = 0;
    }
    /**
     * 向所有注册函数广播。
     * @param args 任意广播信息
     */
    public boardcast(...args:any[]): void {
        let list = this.delegateDataArr;
        for (let i = 0, len = list.length; i < len; i++) {
            let item = list[i];
            let fun = item.fun;
            let thisArg: any = item.thisObj;
            if (thisArg) {
                fun.apply(thisArg, args);
            } else {
                fun(args);
            }
        }
    }
}

export class DelegateData {
    fun: Function = null!;
    thisObj: any;
}
