import { Component, director, instantiate, Prefab, _decorator, Node, Sprite, SpriteFrame, assetManager, Camera, NodeEventType } from "cc";
import { EntryManager } from "../framework/hall/entry/EntryManager";
import { UILayer } from "../framework/ui/UILayer";
import { UIManager } from "../framework/ui/UIManager";
import { LoadingManager } from "../load/LoadingManager";
import { Global } from "../main/Global";
import ComponentMgr from "../mgr/ComponentMgr";
import UIUtils from "../framework/ui/UIUtils";
import { ResManager } from "../framework/manager/ResManager";
import { GameUtils } from "../common/utils/GameUtil";
import { ENTER_GAME_ERR_CODE, GameConst, LOGO_PLAY_TYPE } from "../main/GameConst";
import { Eventer } from "../framework/Eventer";
import { Events } from "../framework/Events";
import { ScreenType } from "../framework/ui/UIView";
import { GameManager } from "../mgr/GameManager";
import { UIID } from "../framework/ui/UIDefined";
import { GameData } from "../framework/hall/data/GameData";
const { ccclass, property } = _decorator;

@ccclass('GameEnterScene')
export class GameEnterScene extends Component {

    @property(Camera)
    camera: Camera = null;

    @property(Prefab)
    uiLayer: Prefab = null;

    @property(Sprite)
    poster: Sprite = null;

    @property(Sprite)
    poster_ver: Sprite = null;

    addUILayer() {
        let uiLayer = UIManager.getInstance().uiLayer as UILayer;
        if (!uiLayer) {
            let node = instantiate(this.uiLayer);
            director.addPersistRootNode(node);
        }
    }

    start() {
        GameData.gameStartTime = new Date().getTime();
        this.changeScreen();
        this.addEvent();
    }

    onLoad() {
        Global.camera = this.camera;
        this.addUILayer();
        this.loadCfg();
    }

    /**
     * 展示加载图
     */
    private showPoster() {
        if (!Global.premissionToEnterGame)
            return;
        ResManager.Instance().loadRemoteImg(GameUtils.getPosterByid(Global.gameId), true,
            (spriteFrame: SpriteFrame) => {
                this.poster.node.active = false;
                this.poster.spriteFrame = spriteFrame;
            });
        if (GameConst.isHasVerLoading(Global.gameId))
            ResManager.Instance().loadRemoteImg(GameUtils.getVerPosterByid(Global.gameId), true,
                (spriteFrame: SpriteFrame) => {
                    this.poster_ver.node.active = false;
                    this.poster_ver.spriteFrame = spriteFrame;
                });
    }

    /**
     * 播放Logo动画
     */
    private async playLogoAni() {
        await UIManager.getInstance().open(UIID.UICover);
        await UIManager.getInstance().open(UIID.UILogo);
        this.showPoster();
        this.enterGame();
    }

    /**
     * 播放logo结束
     */
    private logoPlayEnd() {
        this.changeScreen();
    }

    private loadCfg() {
        LoadingManager.getInstance().loadInitConfig(this.playLogoAni.bind(this));

        ComponentMgr.getInstance().init();
        EntryManager.getInstance().init();
        GameManager.getInstance().init();
    }

    private enterGame() {
        if (!Global.premissionToEnterGame) {
            switch (Global.premissionEnterGameCode) {
                case ENTER_GAME_ERR_CODE.IP_RESTRICT:
                    UIUtils.showPopupView(40001); break;
                case ENTER_GAME_ERR_CODE.INVALID_URL:
                    UIUtils.showPopupView(40002); break;
            }
            return;
        }

        console.log("###Enter Game###");
        this.mark();
        // AudioManager.Instance().stopMusic();
        EntryManager.getInstance().loadCommonConfig(Global.gameId.toString());
        EntryManager.getInstance().enterGame(Global.gameId.toString());
    }

    private changeScreen() {
        if (Global.gameScreenType == ScreenType.Portrait) {
            this.poster_ver.node.active = true;
            this.poster.node.active = false;
        } else {
            this.poster_ver.node.active = false;
            this.poster.node.active = true;
        }
    }

    /**
     * 埋点
     */
    private mark() {
        let obj = {
            gameid: Global.gameId
        }
        GameUtils.c2javaMarkByShort('start_the_process', obj);
    }

    private addEvent() {
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
        Eventer.getInstance().on(Events.LogoPlayEnd, this.logoPlayEnd, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
        Eventer.getInstance().offName(Events.LogoPlayEnd, this);
    }

}