import UIAdapter from "./UIAdapter";
import { Node, Component, _decorator, UIOpacity, UITransform, Overflow, warn, BlockInputEvents, UITransformComponent, Size, Layers } from "cc";
import { UIManager } from "./UIManager";
const { ccclass, property, menu } = _decorator;

export enum UIZIndex {
    views = 1,
    actUI,
    popup,
    notice = 999,
    message,
    max,
    record,
    playback,
    cover
}

/** 游戏屏幕样式 */
export enum ScreenType {
    /** 横屏 */
    Landscape = "landscape",
    /** 竖屏 */
    Portrait = "portrait",
}

/**
 * UIView界面基础类
 * 注意： uiview的根节点宽高不能为0
 */
@ccclass
@menu("ui/common/UIView")
export class UIView extends Component {
    uiId: number;
    /** 开启打开关闭动画 */
    @property({ displayName: "开启动画" })
    bAni: boolean = false;
    /** 快速关闭 */
    @property({ displayName: "快速关闭" })
    quickClose: boolean = false;
    /** 缓存选项 没勾选，则每次打开界面都会调用init，并且关闭时候会destroy*/
    @property({ displayName: "缓存选项" })
    cache: boolean = false;
    /** 遮罩 */
    @property({ displayName: "是否添加遮罩" })
    isMask: boolean = false;
    /** 开启子节点动画 */
    // @property({ displayName: "开启子节点动画" })
    // bChildAni: boolean = false;
    /** 界面背景图 用来设置快速关闭、及打开和关闭动画*/
    @property({
        type: Node,
        displayName: "界面背景图",
        tooltip: "界面背景图 用来设置快速关闭、及打开和关闭动画",
    })
    background: Node = null;

    onLoad() {
        this.node.addComponent(UIAdapter);
    }

    /**
     * 1:有缓存则只执行一次，没勾选缓存则每次打开界面都会执行
     * 当界面被创建时回调，生命周期内只调用
     * @param args 可变参数
     */
    init(...args): void { }

    /**
     * 2:当界面被打开时回调，每次调用Open时回调
     * @param args 可变参数
     */
    onOpen(...args): void { }

    /**
     * 3:每次界面Open动画播放完毕时回调
     */
    onOpenAniOver(): void { }

    /**
     * 当界面被关闭时回调，每次调用Close时回调
     * 返回值会传递给下一个界面
     */
    onClose(): any { }

    close() {
        UIManager.getInstance().close(this);
    }

    setZIndex(zIndex: number) {
        // this.node.setSiblingIndex(zIndex);
        this.node.zIndex = zIndex;
    }

    /**
     * 加个遮罩屏蔽点击 用于虚宝卡
     * @param clickable 
     */
    setClickEnabled(clickable: boolean) {
        let clickMaskNode = this.node.getChildByName("ClickMaskNode");
        if (!clickMaskNode) {
            clickMaskNode = new Node("ClickMaskNode");
            clickMaskNode.layer = Layers.Enum.UI_2D;
            let transform = clickMaskNode.addComponent(UITransform);
            transform.setAnchorPoint(0.5, 0.5);
            transform.setContentSize(new Size(1280, 720));
            clickMaskNode.addComponent(BlockInputEvents);
            this.node.addChild(clickMaskNode);
        }

        if (!clickable) clickMaskNode.active = true;
        else clickMaskNode.active = false;
    }
}
