import { _decorator, Component, Node, Mask, Enum, CCInteger, UITransform } from 'cc';
const { ccclass, property } = _decorator;

/**
 * @en The type for mask graphcis.
 *
 * @zh graphcis遮罩组件类型。
 */
export enum GRAPHCIS_TYPE {
    /**
     * @zh
     * 圆角遮罩。
     */
    ANGLE_ROUNDED = 0,
}

@ccclass('UIMask_I')
export class UIMask_I extends Mask {

    private _graphcisType: GRAPHCIS_TYPE;
    get graphcisType(): GRAPHCIS_TYPE {
        return this._graphcisType;
    }

    @property({
        displayName: "graphcisType", type: Enum(GRAPHCIS_TYPE), tooltip: "GRAPHICS_STENCIL 的类型设置",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL;
        },
    })
    set graphcisType(value: GRAPHCIS_TYPE) {
        if (this._graphcisType === value) {
            return;
        }
        this._graphcisType = value;
        this.drawGraphicsMask();
    }

    @property
    private _radius = 10;
    /**
     * @en Radius of rectangular rounded corners.
     * @zh 矩形圆角半径。
     */
    @property({
        displayName: "radius", type: CCInteger, tooltip: "圆角半径",
        visible: function () {
            return this.type === Mask.Type.GRAPHICS_STENCIL && this._graphcisType === GRAPHCIS_TYPE.ANGLE_ROUNDED;
        },
    })
    public set radius(val: number) {
        this._radius = val;
        this.drawGraphicsMask();
    }
    public get radius() {
        return this._radius;
    }

    start() {
        this.drawGraphicsMask();
    }

    /** 绘制滚动条的遮罩 */
    private drawGraphicsMask(): void {
        if (!this._graphics || this._type !== Mask.Type.GRAPHICS_STENCIL) {
            return;
        }
        this._graphics.clear();
        const uiTrans = this.node.getComponent(UITransform);
        const size = uiTrans.contentSize;
        const width = size.width;
        const height = size.height;
        const ap = uiTrans.anchorPoint;
        const x = -width * ap.x;
        const y = -height * ap.y;
        this._graphics.roundRect(x, y, width, height, this.radius);
        this._graphics.fill();
    }
}
