import { _decorator, Component } from "cc";
const { ccclass } = _decorator;

@ccclass("PRichText")
export class PRichText extends Component {
    _cb: Function = null!;
    start() {}
    initCb(cb: Function = null) {
        this._cb = cb;
    }
    update(deltaTime: number) {}

    clickHyperLink(evet, paramStr, c) {
        let param = {};
        if (paramStr) {
            param = JSON.parse(paramStr);
        }
        if (this._cb) {
            this._cb(param);
        }
    }
}
