
export default class DateUtil {
    /**
     * 格式化时间函数
     * let dateStr = formatDate("yyyy/MM/dd hh:mm:ss", timestamp)
     * @param format
     * @param timestamp
     * @returns
     */
    public static formatDate(format: string, timestamp: number): string {
        let date = new Date();
        date.setTime(timestamp * 1000);
        let o = {
            'M+': date.getMonth() + 1, //月份
            'd+': date.getDate(), //日
            'h+': date.getHours(), //小时
            'm+': date.getMinutes(), //分
            's+': date.getSeconds(), //秒
            'q+': Math.floor((date.getMonth() + 3) / 3), //季度
            S: date.getMilliseconds(), //毫秒
        };
        if (/(y+)/.test(format))
            format = format.replace(RegExp.$1, (date.getFullYear() + '').substr(4 - RegExp.$1.length));
        for (let k in o)
            if (new RegExp('(' + k + ')').test(format))
                format = format.replace(
                    RegExp.$1,
                    RegExp.$1.length == 1 ? o[k] : ('00' + o[k]).substr(('' + o[k]).length)
                );
        return format;
    }

    /**
     * 根据秒数格式化时间
     * @param time 时间戳（秒）
     * @param format 格式化
     */
     public static formatCountDwon(time: number, format: string): string {
         if(format == "ss") {
             return  Math.floor((time % 3600) % 60) + "s";
         }
        let o = {
            'h+': Math.floor(time / 3600), //小时
            'm+': Math.floor((time % 3600) / 60), //分
            's+': Math.floor((time % 3600) % 60), //秒
        };
        for (let k in o)
            if (new RegExp('(' + k + ')').test(format))
                format = format.replace(
                    RegExp.$1,
                    RegExp.$1.length == 1 ? o[k] : ('00' + o[k]).substr(('' + o[k]).length)
                );
        return format;
    }


}
