import {
    _decorator,
    Component,
    Node,
    Button,
    Enum,
    EventTouch,
    NodeEventType,
    Label,
    CCFloat,
    Vec3,
    Color,
    UIRenderer,
} from "cc";
import { SoundDefine, SoundNameEnum } from "../../../common/define/ResDefine";
import LogUtil from "../../../common/utils/LogUtil";
import AudioManager from "../../manager/AudioManager";
import { Eventer } from "../../Eventer";
import { Events } from "../../Events";
const { ccclass, property, menu, requireComponent, disallowMultiple } =
    _decorator;

@ccclass("UIButton")
@menu("ui/basic_ui/UIButton")
@disallowMultiple(true)
/**
 * 普通按钮
 *  @desc 不要自行监听事件，统一使用
 * touchBeganFun(target),
 * touchMoveFun(target),
 * touchEndedFun(target),
 * touchCancelFun(target)
 * 按钮数据： buttonData
 * 按钮cd：btnCD
 *  @author ice
 */
export class UIButton extends Button {
    @property({
        displayName: "btnCD",
        type: CCFloat,
        tooltip: "按钮点击后的冷却时间，单位：秒",
    })
    public btnCD: number = 0.5;
    @property({ displayName: "btnLable", type: Label, tooltip: "按钮标签" })
    public btnLable: Label;
    /**按钮声音名称 */
    private _soundNameStr: string;
    @property
    private _soundName: SoundNameEnum = SoundNameEnum.sound_click;
    @property({
        type: Enum(SoundNameEnum),
        tooltip: "按钮声音",
    })
    set soundName(val: SoundNameEnum) {
        this._soundName = val;
        if (val == SoundNameEnum.no_sound) {
            this._soundNameStr = null;
        } else {
            this._soundNameStr = SoundNameEnum[this._soundName];
        }
    }
    get soundName() {
        return this._soundName;
    }

    public touchBeganFun: Function;
    public touchMoveFun: Function;
    public touchEndedFun: Function;
    public touchCancelFun: Function;
    public buttonData: any;

    private _isInCD: boolean = false;
    private _cdTime: number = 0;
    /**
     * @en
     * Whether the Button is disabled.
     * If true, the Button will trigger event and do transition.
     *
     * @zh
     * 按钮事件是否被响应，如果为 false，则按钮将被禁用。
     */
    get interactable() {
        return this._interactable;
    }
    set interactable(value) {
        // if (this._interactable === value) {
        //     return;
        // }

        this._interactable = value;
        this._updateState();

        if (!this._interactable) {
            this._resetState();
        }
    }

    public __preload() {
        super.__preload();

        this.node.on(Node.EventType.TOUCH_END, this.onTouchEnded, this);
        this.node.on(Node.EventType.TOUCH_START, this.onTouchBegan, this);
        this.node.on(Node.EventType.TOUCH_MOVE, this.onTouchMove, this);
        this.node.on(Node.EventType.TOUCH_CANCEL, this.onTouchCancel, this);

        if (this._soundName == SoundNameEnum.no_sound) {
            this._soundNameStr = null;
        } else {
            this._soundNameStr = SoundNameEnum[this._soundName];
        }
    }
    update(deltaTime: number) {
        super.update(deltaTime);

        const target = this.target;
        if (!target) {
            return;
        }

        if (this._transition === Button.Transition.COLOR) {
            const renderComp = target.getComponent(UIRenderer);
            if (renderComp) {
                target.children.forEach((child) =>
                    this.updateChildColor(child, renderComp.color)
                );
            }
        }

        if (this._isInCD == false) {
            return;
        }
        this._cdTime += deltaTime;
        if (this._cdTime >= this.btnCD) {
            this._cdTime = 0;
            this._isInCD = false;
        }
    }

    setColor(color: Color) {
        this.updateChildColor(this.node, color)
    }

    /**
     * 更新子节点的颜色
     * @param node
     * @param color
     */
    private updateChildColor(node: Node, color: Color) {
        const renderComp = node.getComponent(UIRenderer);
        if (renderComp) {
            renderComp.color = color;
        }
        node.children.forEach((child) => this.updateChildColor(child, color));
    }

    private onTouchBegan(event?: EventTouch) {
        // super._onTouchBegan(event);

        // if (!this._interactable || !this.enabledInHierarchy) {
        //     LogUtil.log("按钮已失效。。。");
        //     return;
        // }

        // if (this._isInCD) {
        //     LogUtil.log("按钮在cd中。。。");
        //     return;
        // }
        if (this.touchBeganFun) {
            this.touchBeganFun(this);
        }
    }

    private onTouchMove(event?: EventTouch) {
        // super._onTouchMove(event);
        if (
            !this._interactable ||
            !this.enabledInHierarchy ||
            !this["_pressed"]
        ) {
            return;
        }
        if (!event) {
            return;
        }

        const touch = event.touch;
        if (!touch) {
            return;
        }
        if (this._isInCD) {
            LogUtil.log("按钮在cd中。。。");
            return;
        }
        if (this.touchMoveFun) {
            this.touchMoveFun(this);
        }
    }

    private onTouchEnded(event?: EventTouch) {

        //按钮冷却
        this.node.pauseSystemEvents(true);
        this.scheduleOnce(() => {
            this.node.resumeSystemEvents(true);
        }, this.btnCD);

        if (!this._interactable || !this.enabledInHierarchy) {
            return;
        }

        if (this._isInCD) {
            LogUtil.log("按钮在cd中。。。");
            return;
        }
        if (this._soundNameStr && this._soundNameStr.length > 0) {
            AudioManager.Instance().playEffect(SoundDefine[this._soundNameStr]);
        }
        if (this.touchEndedFun) {
            this.touchEndedFun(this);
        }
        this._cdTime = 0;
        this._isInCD = true;
        Eventer.getInstance().emit(Events.ButtonClickEvent);
    }

    private onTouchCancel(event?: EventTouch) {
        // super._onTouchCancel(event);
        if (this.touchCancelFun) {
            this.touchCancelFun(this);
        }
    }
}
