import { APP_TYPE, StatisticsEvent } from "../../common/define/EnumDefine";
import { IClientGameConfig } from "../../common/define/StructDefine";
import LogUtil from "../../common/utils/LogUtil";
import { Global } from "../../main/Global";
import { eventTrig } from "../../mgr/StatisticsManager";
import { EntryManager } from "../hall/entry/EntryManager";
import { RemoteLoader } from "../manager/ResManager";

export class ResUtil {
    /**加载客户端游戏数据配置*/
    static loadCocosVersionConfig(callback?: Function) {
        eventTrig(StatisticsEvent.LOADED_CONFIG_START);
        let url = `${Global.cdn}/gameupdate/games_version.json?v=${Global.svrTimeMS}`
        RemoteLoader.Instance()
            .loadRemoteJson(url)
            .then((data: any) => {
                let jsonMinor = data.json;
                LogUtil.debug("loadClientPara2," + JSON.stringify(jsonMinor));
                if (jsonMinor) {
                    for (let key in jsonMinor) {
                        EntryManager.getInstance().initBundlesVersion(jsonMinor[key]);
                    }
                }
                callback && callback();
                eventTrig(StatisticsEvent.LOADED_CONFIG_SUCCESS);
            }).catch(() => {
                callback && callback();
                eventTrig(StatisticsEvent.LOADED_CONFIG_SUCCESS);
            })
    }
}