import { HotUpdate } from "../../update/IHotUpdate";
import { Singleton } from "../../Singleton";
import { BundleManager } from "../../manager/BundleManager";
import { Entry } from "./Entry";
import { EntryDelegate } from "./EntryDelegate";
import { assetManager, AssetManager, sys } from "cc";
import { CacheManager } from "../../manager/CacheManager";
import { Global } from "../../../main/Global";
import { HotUpdateManager } from "../../update/HotUpdateManager";
import {
    BUNDLE_FISHING_COMMON,
    BUNDLE_GAME_COMMON,
    BUNDLE_RESOURCES,
    BUNDLE_ROLL_COMMON,
    BUNDLE_TABLE_COMMON,
    ENTRY_CONFIG,
    GAME_COMMON_IDS,
    UIID_GAME_COMMON,
} from "../HallDefind";
import { Eventer } from "../../Eventer";
import { Events } from "../../Events";
import { CustomEventMgr } from "../../../mgr/CustomEventMgr";
import { EventType } from "../../../common/define/EventDefine";
import { UIManager } from "../../ui/UIManager";
import { UIID } from "../../ui/UIDefined";


/** 入口管理 */
export class EntryManager extends Singleton<EntryManager>() {
    private tag = "[EntryManager] : ";
    private _entrys: Map<string, Entry> = null;
    /** 默认代理，可根据自己项目需要重新实现 */
    public delegate: EntryDelegate = null;
    private node: Node | null = null;
    public persistBundles: Array<string> = [];
    /**是否在子游戏 */
    private _isInGame: boolean = false;
    /**进入游戏的id */
    public enterGameId: number = 0;
    /**子游戏版本号 */
    private bundleVers = {};

    constructor() {
        super();
        this._entrys = new Map();
        this.delegate = new EntryDelegate();
    }

    init() {
        this.persistBundles = [
            BUNDLE_RESOURCES,
            BUNDLE_GAME_COMMON,
            BUNDLE_FISHING_COMMON,
            BUNDLE_ROLL_COMMON,
            BUNDLE_TABLE_COMMON,
        ];
        HotUpdateManager.getInstance().init(
            Global.platformId.toString(),
            Global.cdn
        );
    }

    /**
     * 开始下载
     * @param gameId 
     */
    download(gameId: string) {
        let bundle = this.loadConfig(gameId, gameId, true);
        BundleManager.getInstance().downloadingId = Number(gameId);
        this.enterBundle(bundle);
    }

    /**
     * 取消下载
     * @param gameId 
     */
    stopDownload(gameId: string) {
        BundleManager.getInstance().isLoading = false;
        HotUpdateManager.getInstance().updating = false;
    }

    /**
     * 进入子游戏
     */
    enterGame(gameId: string) {
        this.isInGame = true;
        Log.d(`=enterGame=${gameId}=`)
        this.enterGameId = Number(gameId);
        if (this.enterGameId == BundleManager.getInstance().downloadingId)
            BundleManager.getInstance().downloadingId = 0;
        this.loadCommonConfig(gameId.toString());
        this.enterBundle(BUNDLE_GAME_COMMON);
    }

    /**
     * 退出游戏
     */
    exitGame() {
        CustomEventMgr.fire(EventType.SHOW_MAIN_UI, true);
        UIManager.getInstance().closeAll();
        if (Global.gameCtrl) {
            Global.gameCtrl.gameBack();
        }
        this.isInGame = false;
    }

    /**
     * 加載bundle配置
     * @param gameId 
     * @returns 
     */
    loadConfig(bundleId: string, gameId: string, isUpdate: boolean = false) {
        let bundle = bundleId;
        if (GAME_COMMON_IDS[bundleId]) {
            bundle = GAME_COMMON_IDS[bundleId];
        }
        let config = this.delegate.getEntryConfig(bundle);
        if (!config) {
            ENTRY_CONFIG[bundle] = new HotUpdate.BundleConfig(bundle, bundle, isUpdate, Number(gameId));
        } else {
            // ENTRY_CONFIG[bundle].gameId = Number(gameId);
            ENTRY_CONFIG[bundle].hasUpdate = isUpdate;
        }
        return bundle;
    }

    /**
     * 加载公共配置
     * @param gameId 
     */
    loadCommonConfig(gameId: string) {
        Object.keys(GAME_COMMON_IDS).forEach(value => {
            this.loadConfig(value, gameId);
        });
        this.loadConfig(gameId, gameId);
    }

    /** 注册入口 */
    register(entryClass: EntryClass<Entry>) {
        let entry = this.getEntry(entryClass.bundle);
        if (entry) {
            this._entrys.delete(entryClass.bundle);
        }
        entry = new entryClass();
        entry.bundle = entryClass.bundle;
        this._entrys.set(entry.bundle, entry);
        // Log.d(`====register==${entry.bundle},${entry}========`)
        if (this.node) {
            entry.onLoad(this.node);
        }
    }

    onLoad(node: Node) {
        this.node = node;
        this._entrys.forEach((entry, key) => {
            if (!entry.isRunning) {
                entry.onLoad(this.node);
                if (entry.isMain) {
                    //启动主程序入口
                    entry.onEnter();
                }
            }
        });
    }

    onDestroy(node: Node) {
        this._entrys.forEach((entry) => {
            entry.onDestroy();
        });
    }

    /** 主包检测更新 */
    onCheckUpdate() {
        this.delegate.onCheckUpdate();
    }

    call(bundle: BUNDLE_TYPE, eventName: string, ...args: any[]) {
        let entry = this.getEntry(bundle);
        if (entry) {
            entry.call(eventName, args);
        }
    }

    /**
     *  进入bundle,默认代理没办法满足需求的情况，可自行定制
     * @param bundle bundle
     **/
    enterBundle(bundle: string) {
        let config = this.delegate.getEntryConfig(bundle);
        if (config) {
            BundleManager.getInstance().enterBundle(config, this.delegate);
        }
        Eventer.getInstance().emit(Events.BundleEnter, bundle);
    }

    /**
     * 退出bundle
     * @param bundle
     */
    exitBundle(bundle: string, isRelease: boolean = true) {
        //在排除bundle中找不到，直接删除
        EntryManager.getInstance().onUnloadBundle(bundle);

        if (isRelease) {

            let result = BundleManager.getInstance().getBundle(bundle);
            if (result) {
                result.releaseAll();
                assetManager.removeBundle(result);
                CacheManager.getInstance().removeBundle(bundle);
            }

        }

        Log.d(`=====exitBundle===${bundle}`)
        this.enterGameId = 0;
        Eventer.getInstance().emit(Events.BundleExit, bundle);
    }


    /** 加载bundle完成 */
    onLoadBundleComplete(
        versionInfo: HotUpdate.BundleConfig,
        bundle: AssetManager.Bundle
    ) {
        //通知入口管理进入bundle
        let entry = this.getEntry(versionInfo.name);
        Log.d(`====onLoadBundleComplete==${versionInfo.name},${entry}========`)
        if (entry) {
            this.onEnterBundle(versionInfo.name);
            entry.onEnter();
        }
    }

    /** 进入GameView完成，卸载除了自己之外的其它bundle */
    onEnterBundle(bundle: BUNDLE_TYPE) {
        let entry = this.getEntry(bundle);
        this.delegate.onEnterBundle(entry);
    }

    /** bundle管事器卸载bundle前通知 */
    onUnloadBundle(bundle: BUNDLE_TYPE) {
        let entry = this.getEntry(bundle);
        if (entry) {
            entry.onUnloadBundle();
        }
    }

    /** 获取bundle入口 */
    getEntry(bundle: BUNDLE_TYPE) {
        let name = BundleManager.getInstance().getBundleName(bundle);
        let entry = this._entrys.get(name);
        if (entry) {
            return entry;
        }
        return null;
    }

    checkUpdatePersistBundles() { }

    set isInGame(flag: boolean) {
        this._isInGame = flag;
    }

    get isInGame() {
        return this._isInGame;
    }

    /**
     * 初始化bundle版本
     */
    initBundlesVersion(bundleVers: any) {
        if (!sys.isBrowser) return;
        try {
            let setttingsAssets = window['cc']?.settings?._settings?.assets;
            if (setttingsAssets && bundleVers && Object.keys(bundleVers).length > 0) {
                this.bundleVers = bundleVers;
                for (let key in bundleVers) {
                    if (setttingsAssets['bundleVers'] && !setttingsAssets['bundleVers'][key]) {
                        setttingsAssets['bundleVers'][key] = bundleVers[key];
                    }
                    if (setttingsAssets['projectBundles']) {
                        if (!setttingsAssets['projectBundles'][key]) {
                            setttingsAssets['projectBundles'].push(key);
                        }

                    }
                }
                Log.d(`修改settings成功！`)
            }
        } catch (error) {
            Log.w(`修改settings失败！`)
        }
    }

    /**
     * 根据budnle或者版本号
     * @param bundle 
     * @returns 
     */
    getBundleVersion(bundle: string) {
        if (!sys.isBrowser) return;
        if (this.bundleVers && this.bundleVers[bundle])
            return this.bundleVers[bundle];
    }
}
