import { _decorator, Component, Node, UITransform, CCInteger, Vec2, CCFloat } from "cc";
const { ccclass, property, menu, disallowMultiple } = _decorator;

@ccclass("UIProgressBar")
@menu("ui/basic_ui/UIProgressBar")
@disallowMultiple(true)
/**
 * 可带特效的进度条 <br/>
 * @author ice
 */
export class UIProgressBar extends Component {
    @property
    protected _barNode: Node | null = null;
    @property({
        displayName: "barNode",
        type: Node,
        tooltip: "bar的节点",
    })
    get barNode() {
        return this._barNode;
    }
    set barNode(value: Node) {
        this._barNode = value;
        this.initBarSprite();
    }
    @property
    protected _progress = 0.1;
    @property({
        type: CCFloat,
        range: [0, 1, .1],
        tooltip:'progress',
        slide: true,
    })
    get progress() {
        return this._progress;
    }
    set progress(value) {
        if (this._progress === value) {
            return;
        }
        this._progress = value;
        this.updateBarStatus();
    }

    /**
     * @en
     * The total width or height of the bar.
     *
     * @zh
     * 进度条实际的总长度。
     */
    @property
    protected _totalLength: number = 1;
    @property({
        displayName: "totalLength",
        type: CCInteger,
        tooltip: "进度条实际的总长度",
    })
    get totalLength() {
        return this._totalLength;
    }

    set totalLength(value) {
        if (this._totalLength === value) {
            return;
        }

        this._totalLength = value;
        this.updateBarStatus();
    }

    // start() {}
    // update(deltaTime: number) {}

    protected initBarSprite() {
        if (this._barNode) {
            let entity = this._barNode;
            if (!entity) {
                return;
            }

            let trans = this.node.getComponent(UITransform);
            let nodeSize = trans.contentSize;
            let nodeAnchor = trans.anchorPoint;

            if (entity.parent === this.node) {
                let x = -nodeSize.width * nodeAnchor.x;
                entity.setPosition(x, 0, 0);
            }
        }
    }

    protected updateBarStatus() {
        if (!this._barNode) {
            return;
        }

        let entity = this._barNode;
        if (!entity) {
            return;
        }

        let progress = this.clamp01(this._progress);
        let actualLenth = this._totalLength * progress;
        this.node.getComponent(UITransform).width = actualLenth;
    }

    /**
     * @en Clamps a value between 0 and 1.<br/>
     * @zh 将值限制在0和1之间。
     * @param val
     */
    private clamp01(val: number) {
        return val < 0 ? 0 : val > 1 ? 1 : val;
    }
}
