import WebSock from "./WebSock";
import { SocketBase, SocketEvent } from "./SocketBase";
import { TencentSocket } from "./TencentSocket";
import { Singleton } from "../Singleton";
import { Eventer } from "../Eventer";
import { Scheduler, director, sys, js, ISchedulable, macro } from "cc";
import { NetAdaptor } from "./NetAdaptor";
import { ProtoUtil } from "../../common/utils/ProtoUtil";
import UIUtils from "../ui/UIUtils";

export type ErrorCallBack = (msgId: number, message: any) => boolean;
export interface RespondParams<T> {
    message: T;
    type: number;
    errCode?: number;
    msg?: string;
}
export type ResCallback<T = any> = (data?: T) => void;
export type EventObject = { listener: any; handler: ResCallback };
export type EventerDispatchers = Map<number, Array<EventObject>>;
export type MessageObject<T = any> = { type: number; message: T };

/**
 * 网络定制处理
 */
export interface NetCustom {
    /**发送心跳消息号 */
    cHeartBeatCode?: number;
    /**接收心跳消息号 */
    sHeartBeatCode?: number;
    /**错误回调 */
    errorCallBack?: Function;
    /**忽略打印的消息号 */
    logFilterCodes?: number[];
    /**需要压缩的消息号 */
    zipCodes?: number[];
}

/**最大重连时间 毫秒*/
const maxReconnectTime = 10000;
/**每次重连时间 毫秒*/
const onceReconnectTime = 500;
/**重连间隔 */
const intervalTtime = 8;

/**
 * 消息注册分发类
 */
export default class SocketManager
    extends Singleton<SocketManager>()
    implements ISchedulable {
    /**socket类 */
    socket: SocketBase = null;
    /**事件分发数组 */
    private rcvMsgListeners: EventerDispatchers = null;
    /**定时器 */
    private scheduler: Scheduler = null;
    /**网络链接状态 */
    isConnect: boolean = false;
    /**登录到服务器标识 */
    private isStartGame: boolean = false;
    /**断线重连开关heartbeat */
    private closeHeartBeat: boolean = true;
    /**心跳消息重连时间 */
    private heatTime: number = 4;
    /**发送心跳时间 */
    private heartbeatCD: number = this.heatTime;
    /**当前时间间隔 */
    private curReplayInterval: number = 0;
    /**网络定制处理 */
    private netCustom: NetCustom = null;
    /**请求参数 */
    private resParam: string = null;
    /**当前重连次数 */
    private curReconnectCount = 0;
    uuid: string = "1";
    private isCanReConnect = false;
    private timeOutHandler = null;

    /**
     * 构造函数
     */
    constructor() {
        super();
        this.rcvMsgListeners = new Map<number, Array<EventObject>>();
        Scheduler.enableForTarget(this);
        this.scheduler = director.getScheduler();
    }

    /**
     * 消息发送
     * @param code 消息号
     * @param data 消息体
     */
    sendMessage<T>(code: number, data?: T | any): void {
        data = data ?? {};
        if (!this.isConnect) return;
        let message: MessageObject = {
            type: code,
            message: data,
        };
        js.mixin(data, ProtoUtil.getParam(data));
        if (this.resParam) js.mixin(message, this.resParam);
        if (!this.isLogFilter(code)) Log.d("Socket Send", message);
        this.socket.send(JSON.stringify(message));
    }

    /**
     * 每帧执行
     * @param dt
     */
    update(dt: number): void {
        //心跳检测
        // if (this.isStartGame) {
        //     if (this.heartbeatCD >= 0) {
        //         this.heartbeatCD -= dt;
        //         if (this.heartbeatCD < 0) {
        //             this.sendHeartbeat();
        //         }
        //     } else {
        //         this.curReplayInterval += dt;
        //         if (this.curReplayInterval >= intervalTtime) {
        //             this.heartbeatCD = this.heatTime;
        //             this.reLogin();
        //         }
        //     }
        // }
    }

    /**
     * 网络注册事件
     */
    private addSocketListener(): void {
        this.socket.addListener(
            SocketEvent.Open,
            this.onSocket.bind(this, SocketEvent.Open)
        );
        this.socket.addListener(
            SocketEvent.Close,
            this.onSocket.bind(this, SocketEvent.Close)
        );
        this.socket.addListener(
            SocketEvent.Message,
            this.onSocket.bind(this, SocketEvent.Message)
        );
        this.socket.addListener(
            SocketEvent.Error,
            this.onSocket.bind(this, SocketEvent.Error)
        );
    }

    /**
     * 断线重连
     */
    reLogin(): void {
        // if (!this.isConnect) return;
        // this.isConnect = false;
        // this.isCanReConnect = true;
        // // UIUtils.showLoading();
        // this.closeHeartBeat = true;
        // this.close();
    }

    close(): void {
        this.scheduler.unschedule(this.update, this);
        if (this.socket) {
            this.socket.close();
        }
    }

    /**
     * websocket需要在收到onClose才能再建立连接
     */
    onClose() {
        if (this.isConnect) {
            this.reLogin();
        }
        if (this.isCanReConnect) {
            this.reLoginEvent();
        } else {
            this.timeOutHandler = setTimeout(() => {
                this.reLoginEvent();
            }, onceReconnectTime);
        }
    }

    reLoginEvent() {
        this.isCanReConnect = false;
        this.curReconnectCount++;
        Log.d(`==reLoginEvent1===${this.curReconnectCount}===`)
        if (this.curReconnectCount < Math.floor(maxReconnectTime / onceReconnectTime)) {
            Eventer.getInstance().emit(SocketEvent.ReLogin);
        } else {
            this.curReconnectCount = 0;
            if (this.timeOutHandler) clearTimeout(this.timeOutHandler);
            UIUtils.netErrorTips(null, this.onClose.bind(this));
        }
    }

    /**
     * 网络事件触发
     * @param socketEventType 事件类型
     * @param message 消息体
     */
    private onSocket(socketEventType: SocketEvent, message: any): void {
        if (socketEventType != SocketEvent.Message)
            Log.d(`${socketEventType}: ${message}`);
        switch (socketEventType) {
            //连接成功
            case SocketEvent.Open: {
                UIUtils.hideLoading();
                this.isStartGame = true;
                this.isConnect = true;
                this.curReconnectCount = 0;
                this.isCanReConnect = false;
                this.resetHeartBeat();
                if (this.timeOutHandler) clearTimeout(this.timeOutHandler);
                this.scheduler.schedule(this.update, this, 0);
                Eventer.getInstance().emit(SocketEvent.Open);
                break;
            }
            //断开连接
            case SocketEvent.Close: {
                this.onClose();
                Eventer.getInstance().emit(SocketEvent.Close);
                break;
            }
            //接收消息
            case SocketEvent.Message: {
                this.dispatchMessage(JSON.parse(message));
                break;
            }
            //网络异常
            case SocketEvent.Error: {
                this.reLogin();
                break;
            }
            default: {
            }
        }
    }

    /**
     * 注册消息
     * @param msgId 消息号
     * @param handler 回调函数
     */
    registerMsgListener<T>(
        msgId: number,
        _handler: ResCallback<T>,
        target?: any
    ): void {
        if (!this.rcvMsgListeners.has(msgId)) {
            this.rcvMsgListeners.set(msgId, []);
        }
        this.rcvMsgListeners
            .get(msgId)
            .push({ listener: target, handler: _handler });
    }

    /**
     * 触发消息
     * @param data 消息体
     */
    dispatchMessage(message: RespondParams<any> = null): void {
        let msgId: number = 0;
        if (message != null && message.type != null) {
            msgId = message.type;
        }
        if (this.netCustom && msgId === this.netCustom.sHeartBeatCode) {
            this.resetHeartBeat();
            // return;
        }
        if (!this.isLogFilter(msgId))
            Log.d("Socket Recv", JSON.parse(JSON.stringify(message)));
        if (
            this.netCustom &&
            this.netCustom.errorCallBack &&
            this.netCustom.errorCallBack(msgId, message)
        ) {
            return;
        }
        if (NetAdaptor.bAdaptor)
            NetAdaptor.getInstance().recvMessage(msgId, message.message);
        if (!this.rcvMsgListeners.has(msgId)) {
            if (!this.isLogFilter(msgId))
                Log.d("Could not handle Message " + msgId);
            return;
        }
        for (let i = 0; i < this.rcvMsgListeners.get(msgId).length; ++i) {
            let dispatcherItem = this.rcvMsgListeners.get(msgId)[i];
            dispatcherItem.handler.call(
                dispatcherItem.listener,
                message.message
            );
        }
    }

    /**
     * 取消注册
     * @param msgId
     */
    unregisterMsgListener(msgId: number, target?: any): void {
        if (this.rcvMsgListeners.has(msgId)) {
            if (target) {
                for (
                    let i = 0;
                    i < this.rcvMsgListeners.get(msgId).length;
                    ++i
                ) {
                    let dispatcherItem = this.rcvMsgListeners.get(msgId)[i];
                    if (target && dispatcherItem.listener == target) {
                        this.rcvMsgListeners.get(msgId).splice(i, 1);
                    }
                }
            } else {
                this.rcvMsgListeners.delete(msgId);
            }
        }
    }

    /**
     * 取消注册所有
     */
    unregisterAllMsg(): void {
        this.rcvMsgListeners.clear();
    }

    /**
     * 发送心跳包
     */
    private sendHeartbeat(): void {
        if (!this.isStartGame) {
            return;
        }
        if (!this.closeHeartBeat) {
            this.sendMessage(this.netCustom.cHeartBeatCode);
        }
        this.curReplayInterval = 0;
        this.heartbeatCD = -1;
    }

    /**
     * 重置心跳包
     */
    private resetHeartBeat(): void {
        this.heartbeatCD = this.heatTime;
        this.closeHeartBeat = false;
    }

    /**
     * 消息号是否需要过滤
     * @param code
     * @returns
     */
    isLogFilter(code: number) {
        if (
            this.netCustom.logFilterCodes &&
            this.netCustom.logFilterCodes.length > 0
        ) {
            return this.netCustom.logFilterCodes.indexOf(code) != -1;
        }
        return false;
    }

    /**
     * 检测网络是否正常
     * @returns 
     */
    checkNetwork() {
        if (this.isConnect && sys.getNetworkType() == sys.NetworkType.NONE) {
            this.reLogin();
        }
    }
}
