import { CCInteger, CCString, Component, error, Label, warn, _decorator } from "cc";
import { EDITOR } from "cc/env";
import { Global } from "../../main/Global";
import { ELanguage_Type } from "../../common/define/EnumDefine";
import StringUtil from "../../common/utils/StringUtil";
import i18n from "./i18n";

const { ccclass, property, menu } = _decorator;

@ccclass("LangLabelParamsItem")
export class LangLabelParamsItem {
    @property
    key: string = "";
    @property
    value: string = "";
}

@ccclass("LanguageLabel")
@menu("ui/language/LanguageLabel")
export class LanguageLabel extends Component {
    //多语言传参
    private params: string[] = [];

    private languageTypeArr: Array<ELanguage_Type> = []; //如果语言配置为空的情况下，默认全语种

    @property
    private _dataID: number = -1;
    @property
    get dataID(): number {
        return this._dataID || -1;
    }
    set dataID(value: number) {
        this._dataID = value;
        if (!EDITOR) {
            this._needUpdate = true;
        }
    }

    get string(): string {
        let _string = "";
        let _language = "";
        _language = Global.language;
        if (this.languageTypeArr.length > 0) {
            if (this.languageTypeArr.indexOf(Global.language) == -1) {
                _language = ELanguage_Type.EN;
            }
            _string = i18n.tr(this._dataID, _language);
        } else {
            _string = i18n.tr(this._dataID);
        }

        if (!_string) {
            warn("[LanguageLabel] 未找到语言标识，使用dataID替换");
            // _string = this._dataID;
            // _string = "404";
            _string = "";
        }
        return _string;
    }

    set string(str: string) {
        if (str) {
            this.getComponent(Label)!.string = str;
        }
    }

    private changeCb: Function = null!;

    /** 更新语言 */
    language() {
        this._needUpdate = true;
    }

    initFontSize: number = 0;

    onLoad() {
        this._needUpdate = true;
        if (!this.getComponent(Label)) {
            error(this.node.name, this._dataID);
            return;
        }

        if (this.getComponent(Label)) {
            this.initFontSize = this.getComponent(Label)!.fontSize;
        }
    }

    /**
     * 设置语言种类，如果语言配置为空的情况下，默认全语种
     * @param languageTypeArr
     */
    public setLanguageTypeArr(languageTypeArr: Array<ELanguage_Type> = []) {
        this.languageTypeArr = languageTypeArr;
        this._needUpdate = true;
    }

    public setChangeCb(cb: Function) {
        this.changeCb = cb;
    }

    /**
     * 修改多语言参数，采用惰性求值策略
     * @param key 对于i18n表里面的key值
     * @param value 替换的文本
     */
    setParams(params: string[]) {
        this.params = params;
    }
    private _needUpdate: boolean = false;

    update() {
        if (this._needUpdate) {
            this.updateLabel();
            this._needUpdate = false;
        }
    }

    updateLabel() {
        do {
            if (!this._dataID) {
                break;
            }

            let spcomp: any = this.getComponent(Label);
            let newStr = "";
            if (this.params.length > 0) {
                newStr = StringUtil.formatLanguageString(
                    this.string,
                    this.params
                );
            } else {
                newStr = this.string;
            }

            spcomp.string = newStr;
            if (this.changeCb) {
                this.changeCb();
            }
        } while (false);
    }
}
