import LogUtil from "../../utils/LogUtil";

export class HttpRespPack {
    /**
     * http返回的状态码，如200,400,500
     */
    // protected _status:number;

    /** 是否成功 */
    protected _isSuccess: boolean = false;

    protected _data: any;
    protected _code: any;
    protected _msg: any;

    /**
     * 从对象池取出
     * @param isSuccess:boolean
     * @param data
     * @returns {ICacheable}
     */
    // public static create(isSuccess:boolean, data:any):any{
    //     return this._cachePool.pop(HttpRespPack, isSuccess, data);
    // }

    public init(isSuccess: boolean, data: any): void {
        this._isSuccess = isSuccess;
        let obj = data;
        if (obj == null) {
            this._data = null;
            this._code = "";
            this._msg = "";
        } else {

            this._data = obj.data == null ? obj : obj.data;
            this._code = obj.code == null ? "" : obj.code;
            this._msg = obj.msg == null ? "" : obj.msg;
        }

    }

    public clear() {
        this._isSuccess = false;
        this._data = null;
    }

    /**
     * 是否成功
     * @returns {boolean}
     */
    get isSuccess(): boolean {
        return this._isSuccess;
    }

    public get data(): any {
        let tmp = this._data;
        if (!tmp) {
            LogUtil.debug("data is empty");
            this._data = {};
        }
        return this._data;
    }

    public get code(): any {
        return this._code;
    }

    public get msg(): any {
        return this._msg;
    }
}