import { Game, game } from "cc";
import { Singleton } from "../framework/Singleton";

export class GameManager extends Singleton<GameManager>() {

    /** 游戏切后台时间戳 */
    private _gameHideTime: number = 0;
    /** 游戏切回的时间戳 */
    private _gameShowTime: number = 0;

    init() {
        this.registerMsgListener();
    }

    public registerMsgListener() {
        game.on(Game.EVENT_HIDE, () => {
            this.gameHideTime = Date.now();
        })
        game.on(Game.EVENT_SHOW, () => {
            this._gameShowTime = Date.now();
        })
    }

    public removeMsgListener() {
        game.off(Game.EVENT_HIDE, () => {
        })
        game.off(Game.EVENT_SHOW, () => {
        })
    }

    /** 游戏切后台时间戳 */
    public get gameHideTime(): number {
        return this._gameHideTime;
    }

    /** 游戏切后台时间戳 */
    public set gameHideTime(time: number) {
        this._gameHideTime = time;
    }

    /** 游戏切后台总时间长 */
    public get gameHideTotalTime(): number {
        if (this.gameHideTime <= 0)
            return 0;
        let time = this._gameShowTime - this.gameHideTime;
        if (time <= 0)
            return 0;
        return time;
    }
} 