import { HttpMethod, HttpBase } from './HttpBase';

/**
 * http请求类
 */
export class HttpReq {
    /**最大重试次数 */
    public static HTTP_MAX_TRYTIMES = 3;
    /**超时等待时间 */
    public static HTTP_USR_TIMEOUT = 5000;

    public static get(url: string, cb: Function, exparm: any = {}) {
        let xhr = new HttpBase();
        let header = exparm['header'] || { 'Content-Type': 'application/json' };
        let retry = exparm['retry'] || HttpReq.HTTP_MAX_TRYTIMES;
        xhr.timeout = HttpReq.HTTP_USR_TIMEOUT;
        for (const key in header) {
            if (header.hasOwnProperty(key)) {
                const element = header[key];
                xhr.setRequestHeader(key, element);
            }
        }
        let failIdx = 0;
        let listenCb = function (resp, _xhr) {
            if (_xhr.readyState == 4) {
                if (_xhr.status >= 200 && _xhr.status < 300) {
                    Log.d('respdata ---->', xhr.response);
                    if (cb) cb(xhr.response);
                } else {
                    failCb();
                }
            }
        };
        let failCb = function () {
            failIdx += 1;
            if (failIdx > retry) {
                Log.d('raise http timeout! %s', url);
                if (cb) cb(false, 'fail');
            } else {
                Log.d('raise timeout! url is %s||idx is %d', url, failIdx);
                xhr.resend();
            }
        };
        xhr.open(url, listenCb, failCb, HttpMethod.GET);
        Log.d('http get ---->', url);
        xhr.send();
    }

    public static post(url: string, cb: Function, senddata: any, exparm: any = {}) {
        let xhr = new HttpBase();
        let header = exparm['header'] || { 'Content-Type': 'application/json' };
        let retry = exparm['retry'] || HttpReq.HTTP_MAX_TRYTIMES;
        xhr.timeout = HttpReq.HTTP_USR_TIMEOUT;
        for (const key in header) {
            if (header.hasOwnProperty(key)) {
                const element = header[key];
                xhr.setRequestHeader(key, element);
            }
        }
        let failIdx = 0;
        let listenCb = function (resp, _xhr) {
            if (_xhr.readyState == 4) {
                if (_xhr.status >= 200 && _xhr.status < 300) {
                    Log.d('respdata ---->', xhr.response);
                    if (cb) cb(xhr.response);
                } else {
                    failCb();
                }
            }
        };
        let failCb = function () {
            failIdx += 1;
            if (failIdx > retry) {
                Log.d('raise http timeout! %s', url);
                if (cb) cb(false, 'fail');
            } else {
                Log.d('raise timeout! url is %s||idx is %d', url, failIdx);
                xhr.resend();
            }
        };
        xhr.open(url, listenCb, failCb, HttpMethod.POST);
        xhr.send(JSON.stringify(senddata));
        Log.d('senddata ---->', senddata);
        Log.d('http post ---->', url);
    }
}
